try:
    obj = json.loads(text)
except (json.JSONDecodeError, TypeError) as exc:
    raise ValueError(str(exc)) from exc
if not isinstance(obj, dict):
    raise ValueError('receipt must be a JSON object')
required = ('receipt_id', 'request_id', 'provider', 'status')
for key in required:
    if key not in obj:
        raise ValueError(f'missing required field: {key}')
for key in ('receipt_id', 'request_id', 'provider'):
    if not isinstance(obj[key], str) or not obj[key]:
        raise ValueError(f'{key} must be a nonempty string')
if obj['status'] not in ('delivered', 'rejected'):
    raise ValueError(f"status must be 'delivered' or 'rejected', got {obj['status']!r}")
return {key: obj[key] for key in required}

